#pragma once
#include "industry_topic_sources.hpp"
namespace industryTopicUpdate {
inline QString display(QJsonValue value){return QString::fromUtf8(value.isObject()?QJsonDocument(value.toObject()).toJson(QJsonDocument::Indented):QJsonDocument(value.toArray()).toJson(QJsonDocument::Indented));}
inline QString reading(QJsonObject state,QString key){if(state.isEmpty())return "尚未选择完整产业基线。";if(key=="original")return "最初完整基线原件；旧任务保持停用\n\n"+state.value("originalArchive").toString();auto archive=industryArchive::validate(state.value("archive").toString()).data;if(key=="archive")return "本机产业完整档案；本机取源不表示远端刷新或事实已核验\n\n"+state.value("archive").toString();if(key.startsWith("job:")){for(auto v:state.value("jobs").toArray()){auto j=v.toObject();if(j.value("slot")==key.mid(4))return "原生产业执行记录\n\n"+display(j);}}for(auto kind:{"versions","runs"}){auto prefix=QString(kind)=="versions"?QString("version:"):QString("run:");if(!key.startsWith(prefix))continue;for(auto v:archive.value(kind).toArray()){auto r=v.toObject();if(r.value("id")!=key.mid(prefix.size()))continue;QString out=QString(kind)=="versions"?"产业版本及完整引用正文\n候选/争议/人工状态沿原记录，不因本机更新升级。\n\n":"产业完整运行原件\n\n";out+=display(r);if(QString(kind)=="versions"){for(auto id:r.value("payload").toObject().value("evidenceIds").toArray())for(auto source:archive.value("evidence").toArray()){auto e=source.toObject();if(e.value("id")!=id)continue;auto p=e.value("payload").toObject();out+="\n\n原引用证据 "+e.value("id").toString()+"\n来源 "+e.value("canonicalUrl").toString()+"\n发布时刻 "+(p.value("publishedAt").isString()?p.value("publishedAt").toString():QString("未提供"))+"\n获取/本机读取原记录\n"+display(p)+"\n\n完整正文\n"+p.value("text").toString("原档未提供正文；不补造");}}return out;}}throw std::runtime_error("所选历史原件已缺失，未显示替代版本");}
inline QJsonArray history(QJsonObject state,QString topic){QJsonArray out;if(state.isEmpty())return out;auto archive=industryArchive::validate(state.value("archive").toString()).data;for(auto kind:{"versions","runs"})for(auto v:archive.value(kind).toArray()){auto r=v.toObject();if(!topic.isEmpty()&&r.value("topicId")!=topic)continue;bool version=QString(kind)=="versions";out.append(QJsonObject{{"key",(version?QString("version:"):QString("run:"))+r.value("id").toString()},{"label",(version?QString("版本 #%1").arg(r.value("sequence").toInt()):QString("运行 ")+r.value("status").toString())+" · "+r.value("id").toString()}});}for(auto v:state.value("jobs").toArray()){auto j=v.toObject();if(topic.isEmpty()||j.value("topicId")==topic)out.append(QJsonObject{{"key","job:"+j.value("slot").toString()},{"label","执行 "+j.value("status").toString()+" · "+j.value("startedAt").toString()}});}return out;}
class Draft final{
 QString file;
 static void check(QJsonObject d){watchlistBackup::keys(d,{"schema","baseline","topic","sourceIds","sourceUrls","proposals","enabled","interval","mode","readingKey","segment"});need(d.value("schema")=="native-industry-update-draft/v1","产业草稿格式无效");for(auto k:{"baseline","topic","sourceUrls","proposals","interval","readingKey"})need(d.value(k).isString(),"完整草稿文字字段缺失");need(d.value("enabled").isBool()&&d.value("mode").isDouble()&&d.value("mode").toDouble()==d.value("mode").toInt()&&d.value("mode").toInt()>=0&&d.value("mode").toInt()<=2&&d.value("segment").isDouble()&&d.value("segment").toDouble()==d.value("segment").toInt()&&d.value("segment").toInt()>=0,"草稿位置无效");auto ids=d.value("sourceIds").toArray();need(d.value("sourceIds").isArray()&&ids.size()<=20,"草稿来源超限");QSet<QString>seen;for(auto v:ids){auto id=v.toString();need(v.isString()&&QRegularExpression("^(docs|collections):.{1,200}$").match(id).hasMatch()&&!seen.contains(id),"草稿来源身份无效/重复");seen.insert(id);}unifiedBackup::sensitive(d);auto parsed=QJsonDocument::fromJson(d.value("proposals").toString().toUtf8());if(parsed.isObject())unifiedBackup::sensitive(parsed.object());else if(parsed.isArray())unifiedBackup::sensitive(parsed.array());}
 QByteArray bytes()const{QFile f(file);if(!f.exists())return {};need(f.open(QIODevice::ReadOnly)&&f.size()<=16*1024*1024,"产业完整草稿超限/不可读，原件保留");auto bytes=f.readAll();auto text=QString::fromUtf8(bytes);need(text.toUtf8()==bytes,"草稿UTF8损坏");watchlistBackup::JsonGate{text}.run();check(json(parse(text)).toObject());return bytes;}
public:
 explicit Draft(QString path):file(std::move(path)){}
 QString marker()const{auto b=bytes();return b.isEmpty()?QString():QString::fromLatin1(QCryptographicHash::hash(b,QCryptographicHash::Sha256).toHex());}
 QJsonObject read(QString expected)const{auto b=bytes();need(!b.isEmpty()&&QString::fromLatin1(QCryptographicHash::hash(b,QCryptographicHash::Sha256).toHex())==expected,"草稿摘要已变，未载入替代版本");return json(parse(QString::fromUtf8(b))).toObject();}
 QString save(QJsonObject d,QString expected)const{check(d);auto b=QJsonDocument(d).toJson(QJsonDocument::Compact);need(b.size()<=16*1024*1024,"完整草稿超限，未裁剪");QLockFile lock(file+".lock");lock.setStaleLockTime(0);need(lock.tryLock(0),"草稿正在由另一窗口保存");need(marker()==expected,"草稿已变，未覆盖另一窗口原件");QSaveFile out(file);out.setDirectWriteFallback(false);need(out.open(QIODevice::WriteOnly)&&out.write(b)==b.size()&&out.commit(),"草稿原子保存失败");return marker();}
};
}
